import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"持久化与崩溃一致性","description":"","frontmatter":{"title":"持久化与崩溃一致性"},"headers":[],"relativePath":"zh/guide/persistence.md","filePath":"zh/guide/persistence.md","lastUpdated":0}`),a={name:`zh/guide/persistence.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_7-持久化与崩溃一致性" tabindex="-1">7. 持久化与崩溃一致性 <a class="header-anchor" href="#_7-持久化与崩溃一致性" aria-label="Permalink to “7. 持久化与崩溃一致性”">​</a></h1><h2 id="_7-1-数据库" tabindex="-1">7.1 数据库 <a class="header-anchor" href="#_7-1-数据库" aria-label="Permalink to “7.1 数据库”">​</a></h2><p>第一版使用 SQLite。</p><p>建议启用 WAL，并根据可靠性要求选择适当的 <code>synchronous</code> 策略。不能假设 WAL 自动保证每条记录都已经持久化，也不需要无条件在每个日志写入后手动执行 fsync。</p><p>对关键恢复操作，应明确事务边界。</p><h2 id="_7-2-核心表" tabindex="-1">7.2 核心表 <a class="header-anchor" href="#_7-2-核心表" aria-label="Permalink to “7.2 核心表”">​</a></h2><p>建议至少包括：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>resources</span></span>
<span class="line"><span>resource_dependencies</span></span>
<span class="line"><span>resource_health</span></span>
<span class="line"><span>incidents</span></span>
<span class="line"><span>recovery_runs</span></span>
<span class="line"><span>recovery_steps</span></span>
<span class="line"><span>probe_results</span></span>
<span class="line"><span>diagnoses</span></span>
<span class="line"><span>action_attempts</span></span>
<span class="line"><span>verification_results</span></span>
<span class="line"><span>audit_events</span></span>
<span class="line"><span>notification_queue</span></span>
<span class="line"><span>notification_attempts</span></span>
<span class="line"><span>plugin_registry</span></span>
<span class="line"><span>configuration_versions</span></span></code></pre></div><p>其中：</p><ul><li><code>resources</code> 保存资源定义。</li><li><code>resource_dependencies</code> 保存依赖关系。</li><li><code>resource_health</code> 保存当前健康快照。</li><li><code>incidents</code> 保存故障生命周期。</li><li><code>recovery_runs</code> 保存恢复任务。</li><li><code>recovery_steps</code> 保存步骤顺序和状态。</li><li><code>probe_results</code> 保存探测证据。</li><li><code>diagnoses</code> 保存诊断结果。</li><li><code>action_attempts</code> 保存每次动作尝试。</li><li><code>verification_results</code> 保存验证结果。</li><li><code>audit_events</code> 保存事件审计。</li><li><code>notification_queue</code> 保存待发送通知。</li><li><code>notification_attempts</code> 保存发送历史。</li><li><code>plugin_registry</code> 保存已加载插件及能力信息。</li><li><code>configuration_versions</code> 保存配置版本或变更摘要。</li></ul><h2 id="_7-3-高风险动作的持久化顺序" tabindex="-1">7.3 高风险动作的持久化顺序 <a class="header-anchor" href="#_7-3-高风险动作的持久化顺序" aria-label="Permalink to “7.3 高风险动作的持久化顺序”">​</a></h2><p>执行高风险动作前：</p><ol><li>校验资源和依赖条件。</li><li>校验动作权限。</li><li>校验预算和互斥锁。</li><li>创建 ActionAttempt。</li><li>将状态标记为 <code>Executing</code>。</li><li>在事务提交成功后执行外部动作。</li><li>记录动作返回结果。</li><li>重新验证资源健康。</li><li>更新 RecoveryRun 状态。</li></ol><p>如果 Custos 在第 6 步期间崩溃，则恢复后必须识别执行结果可能未知。</p><p>不能把“数据库状态写成 Executing”误认为“外部动作一定执行了”，也不能把“外部动作返回 0”误认为“服务一定恢复”。</p><h2 id="_7-4-数据保留" tabindex="-1">7.4 数据保留 <a class="header-anchor" href="#_7-4-数据保留" aria-label="Permalink to “7.4 数据保留”">​</a></h2><p>配置：</p><ul><li>审计记录保留周期。</li><li>探测明细保留周期。</li><li>恢复任务保留周期。</li><li>通知发送记录保留周期。</li><li>数据库大小限制。</li></ul><p>默认不删除仍处于活动状态的 Incident、RecoveryRun 或尚未送达的通知。</p><p>日志压缩或清理必须与活动任务状态分离。</p><hr>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};